"""User-facing error formatting shared by the command and config processors."""
import json
import os


class Panic(Exception):
    def __init__(self, location, message):
        self.location = location
        self.message = message
        super().__init__(message)

    def report(self):
        return (f"\nthread 'main' ({os.getpid()}) panicked at {self.location}:\n"
                f"{self.message}\n"
                'note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n')


def none_error(location):
    raise Panic(location, 'called `Option::unwrap()` on a `None` value')


def item_at(items, index, location):
    if index >= len(items):
        raise Panic(location, f'index out of bounds: the len is {len(items)} but the index is {index}')
    return items[index]


def os_description(error):
    return f'{error.strerror} (os error {error.errno})'


def os_panic(error, location):
    kind = {1: 'PermissionDenied', 2: 'NotFound', 13: 'PermissionDenied',
            17: 'AlreadyExists', 20: 'NotADirectory', 21: 'IsADirectory',
            22: 'InvalidInput', 28: 'StorageFull', 32: 'BrokenPipe',
            36: 'InvalidFilename', 40: 'FilesystemLoop'}.get(error.errno, 'Uncategorized')
    detail = ('Os { code: %d, kind: %s, message: %s }' %
              (error.errno, kind, json.dumps(error.strerror, ensure_ascii=False)))
    raise Panic(location, 'called `Result::unwrap()` on an `Err` value: ' + detail)
