"""A small dependency-free YAML reader for theme documents.

It supports nested mappings and sequences, flow collections, scalar styles,
anchors and aliases. Node types are preserved so a numeric color is not
silently treated as a string.
"""
import json
import re
from dataclasses import dataclass


class YamlError(Exception):
    def __init__(self, text, offset, info):
        self.offset = max(0, min(offset, len(text)))
        self.line = text.count('\n', 0, self.offset) + 1
        start = text.rfind('\n', 0, self.offset) + 1
        self.col = self.offset - start
        self.info = info

    def __str__(self):
        return ('ScanError { mark: Marker { index: %s, line: %s, col: %s }, info: %s }' %
                (self.offset, self.line, self.col, json.dumps(self.info, ensure_ascii=False)))


def plain_scalar(text):
    if text in ('', '~', 'null', 'Null', 'NULL'):
        return None
    if text in ('true', 'True', 'TRUE'):
        return True
    if text in ('false', 'False', 'FALSE'):
        return False
    if re.fullmatch(r'[-+]?\d+', text):
        try:
            n = int(text)
            if -(1 << 63) <= n < (1 << 63):
                return n
        except ValueError:
            pass
    if re.fullmatch(r'[-+]?0x[0-9a-fA-F]+', text):
        try:
            n = int(text, 16)
            if -(1 << 63) <= n < (1 << 63):
                return n
        except ValueError:
            pass
    if re.fullmatch(r'[-+]?0o[0-7]+', text):
        try:
            return int(text, 8)
        except ValueError:
            pass
    if text.lower() in ('.inf', '+.inf', '-.inf', '.nan'):
        return float(text.replace('.', ''))
    if re.fullmatch(r'[-+]?(?:\d+\.\d*|\.\d+|\d+[eE][-+]?\d+)(?:[eE][-+]?\d+)?', text):
        try:
            return float(text)
        except ValueError:
            pass
    return text


@dataclass
class Line:
    start: int
    raw: str
    indent: int
    text: str


def uncomment(text):
    quote = None
    escaped = False
    i = 0
    while i < len(text):
        c = text[i]
        if quote:
            if escaped:
                escaped = False
            elif c == '\\' and quote == '"':
                escaped = True
            elif c == quote:
                if quote == "'" and i + 1 < len(text) and text[i+1] == "'":
                    i += 1
                else:
                    quote = None
        elif c in "\"'" and (i == 0 or text[i-1] in ' :,[{'):
            quote = c
        elif c == '#' and (i == 0 or text[i-1].isspace()):
            return text[:i].rstrip()
        i += 1
    return text.rstrip()


def mapping_colon(text):
    quote = None
    escaped = False
    depth = 0
    for i, c in enumerate(text):
        if quote:
            if escaped:
                escaped = False
            elif c == '\\' and quote == '"':
                escaped = True
            elif c == quote:
                quote = None
        elif c in "\"'" and (i == 0 or text[i-1] in ' :,[{'):
            quote = c
        elif c in '[{':
            depth += 1
        elif c in ']}':
            depth -= 1
        elif c == ':' and depth == 0 and (i+1 == len(text) or text[i+1].isspace()):
            return i
    return None


class Flow:
    def __init__(self, reader, text, start):
        self.reader, self.text, self.start, self.pos = reader, text, start, 0

    def fail(self, info):
        raise YamlError(self.reader.text, self.start + self.pos, info)

    def skip(self):
        while self.pos < len(self.text):
            if self.text[self.pos].isspace():
                self.pos += 1
            elif self.text[self.pos] == '#':
                n = self.text.find('\n', self.pos)
                self.pos = len(self.text) if n < 0 else n+1
            else:
                break

    def word(self):
        start = self.pos
        while self.pos < len(self.text) and not self.text[self.pos].isspace() and self.text[self.pos] not in ',[]{}':
            self.pos += 1
        return self.text[start:self.pos]

    def quoted(self):
        quote = self.text[self.pos]
        self.pos += 1
        out = []
        escapes = {'0':'\0', 'a':'\a', 'b':'\b', 't':'\t', '\t':'\t', 'n':'\n',
                   'v':'\v', 'f':'\f', 'r':'\r', 'e':'\x1b', ' ':' ', '"':'"',
                   '/':'/', '\\':'\\', 'N':'\x85', '_':'\xa0', 'L':'\u2028', 'P':'\u2029'}
        while self.pos < len(self.text):
            c = self.text[self.pos]
            self.pos += 1
            if c == quote:
                if quote == "'" and self.pos < len(self.text) and self.text[self.pos] == "'":
                    out.append("'"); self.pos += 1
                else:
                    return ''.join(out)
            elif c == '\\' and quote == '"':
                if self.pos == len(self.text):
                    break
                c = self.text[self.pos]; self.pos += 1
                if c in escapes:
                    out.append(escapes[c])
                elif c in ('x', 'u', 'U'):
                    n = {'x':2, 'u':4, 'U':8}[c]
                    digits = self.text[self.pos:self.pos+n]
                    if len(digits) != n or not re.fullmatch('[0-9a-fA-F]+', digits):
                        self.fail('while parsing a quoted scalar, did not find expected hexadecimal number')
                    self.pos += n
                    try:
                        out.append(chr(int(digits,16)))
                    except ValueError:
                        self.fail('while parsing a quoted scalar, found invalid Unicode character escape code')
                elif c == '\n':
                    while self.pos < len(self.text) and self.text[self.pos] in ' \t':
                        self.pos += 1
                else:
                    self.fail('while parsing a quoted scalar, found unknown escape character')
            elif c == '\n':
                out.append(' ')
                while self.pos < len(self.text) and self.text[self.pos] in ' \t':
                    self.pos += 1
