                val = self.block_value(value, indent, start)
                try:
                    result[key] = val
                except TypeError:
                    result[repr(key)] = val
        return result

    def load(self):
        docs = []
        while True:
            self.skip()
            if self.i >= len(self.lines):
                break
            if self.lines[self.i].text == '...':
                self.i += 1
                continue
            if self.lines[self.i].text == '---':
                self.i += 1
                self.skip()
                if self.i >= len(self.lines) or self.lines[self.i].text in ('---','...'):
                    docs.append(None)
