            docs.append(self.block(self.lines[self.i].indent))
            self.skip()
            if self.i < len(self.lines) and self.lines[self.i].text not in ('---','...'):
                self.fail(self.lines[self.i], 'did not find expected <document start>')
        return docs


def load(text):
    return Reader(text).load()
