        save_config(config, output, writer)
    if options.get('reload'):
        try:
            subprocess.run(['i3-msg', 'reload'], stdin=subprocess.DEVNULL,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except OSError as error:
            raise Exit(1, error=f'Could not reload config with i3-msg: {os_description(error)}\n')
    return 0


def main(args=None, program=None):
    if args is None:
        args = sys.argv[1:]
    if program is None:
        program = os.path.basename(sys.argv[0])
    try:
        return run(args, program)
    except Exit as result:
        sys.stdout.write(result.output)
        sys.stderr.write(result.error)
        return result.code
    except Panic as panic:
        sys.stdout.flush()
        sys.stderr.write(panic.report())
        return 101
    except BrokenPipeError:
        # Avoid a Python traceback on a closed downstream pipe.
        try:
            sys.stdout = open(os.devnull, 'w')
        except OSError:
            pass
        return 101


if __name__ == '__main__':
    sys.exit(main())
