import json,struct,math,itertools
samples=json.load(open('.probe/alias-samples.json'))
def ulp(x,n):
 return struct.unpack('d',struct.pack('Q',struct.unpack('Q',struct.pack('d',float(x)))[0]+n))[0]
for center,aliases in [((128,128,128),('grey','gray')),((119,136,153),('lightslategrey','lightslategray'))]:
 sub=[(tuple(row[:3]),row[3]) for row in samples if row[3] in aliases]
 best=(len(sub),None)
 for norm in [1,255,256,100]:
  vs=[(tuple(x/norm for x in v),n) for v,n in sub]
  base=tuple(x/norm for x in center)
  for sqrt in [False,True]:
   for order in [(0,1,2),(0,2,1),(1,2,0)]:
    def dist(v,c):
     d=[(x-y)**2 for x,y in zip(v,c)]
     d=d[order[0]]+d[order[1]]+d[order[2]]
     return math.sqrt(d) if sqrt else d
    ds=[dist(v,base) for v,n in vs]
    offsets=itertools.product(range(-2,3),repeat=3) if aliases[0]!='grey' else [(k,k,k) for k in range(-4,5)]
